from AlgorithmImports import *
import math


class TwoSlotStrategyAlgorithm(QCAlgorithm):
    SMA_PERIOD = 20
    RSI_PERIOD = 14
    AAPL_BUY_AMOUNT = 20000.0

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_sma = self.SMA(self.spy, self.SMA_PERIOD, Resolution.Daily)
        self.aapl_rsi = self.RSI(self.aapl, self.RSI_PERIOD, Resolution.Daily)

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.lots = {
            "A": 0,
            "B": 0
        }

        self.pending_orders = {
            "A": None,
            "B": None
        }

        self.SetWarmUp(200, Resolution.Daily)

    def OnData(self, data):
        self._apply_splits(data)

        spy_buy_cross, spy_sell_cross = self._update_spy_state(data)
        aapl_red_three_days = self._update_aapl_state(data)

        if not all(symbol in data.Bars for symbol in self.symbols):
            return

        if self.IsWarmingUp:
            return

        aapl_rsi_above_60 = (
            self.aapl_rsi.IsReady and
            float(self.aapl_rsi.Current.Value) > 60.0
        )

        # Evaluate all sell reasons before any buy reasons.
        if (
            self.lots["A"] > 0 and
            self.pending_orders["A"] is None and
            spy_sell_cross
        ):
            self._submit_sell("A", self.spy)

        if (
            self.lots["B"] > 0 and
            self.pending_orders["B"] is None and
            aapl_rsi_above_60
        ):
            self._submit_sell("B", self.aapl)

        # Slot 1: Strategy A
        if (
            self.lots["A"] == 0 and
            self.pending_orders["A"] is None and
            spy_buy_cross
        ):
            close = float(data.Bars[self.spy].Close)
            portfolio_value = float(self.Portfolio.TotalPortfolioValue)
            quantity = int(math.floor((0.40 * portfolio_value) / close))

            if quantity > 0:
                self._submit_buy("A", self.spy, quantity)

        # Slot 2: Strategy B
        if (
            self.lots["B"] == 0 and
            self.pending_orders["B"] is None and
            aapl_red_three_days
        ):
            available_cash = float(self.Portfolio.Cash)

            if available_cash >= self.AAPL_BUY_AMOUNT:
                close = float(data.Bars[self.aapl].Close)
                quantity = int(math.floor(self.AAPL_BUY_AMOUNT / close))

                if quantity > 0:
                    self._submit_buy("B", self.aapl, quantity)

    def _update_spy_state(self, data):
        if self.spy not in data.Bars:
            return False, False

        bar = data.Bars[self.spy]
        close = float(bar.Close)

        previous_close = self.previous_spy_close
        previous_sma = self.previous_spy_sma

        current_sma = None
        if self.spy_sma.IsReady:
            current_sma = float(self.spy_sma.Current.Value)

        buy_cross = (
            previous_close is not None and
            previous_sma is not None and
            current_sma is not None and
            previous_close <= previous_sma and
            close > current_sma
        )

        sell_cross = (
            previous_close is not None and
            previous_sma is not None and
            current_sma is not None and
            previous_close >= previous_sma and
            close < current_sma
        )

        self.previous_spy_close = close
        if current_sma is not None:
            self.previous_spy_sma = current_sma

        return buy_cross, sell_cross

    def _update_aapl_state(self, data):
        if self.aapl not in data.Bars:
            return False

        close = float(data.Bars[self.aapl].Close)

        if self.previous_aapl_close is None:
            self.aapl_red_streak = 0
        elif close < self.previous_aapl_close:
            self.aapl_red_streak += 1
        else:
            self.aapl_red_streak = 0

        self.previous_aapl_close = close
        return self.aapl_red_streak >= 3

    def _apply_splits(self, data):
        if self.aapl in data.Splits and self.lots["B"] > 0:
            split_factor = float(data.Splits[self.aapl].SplitFactor)
            if split_factor > 0:
                self.lots["B"] = int(self.lots["B"] * split_factor)

        if self.spy in data.Splits and self.lots["A"] > 0:
            split_factor = float(data.Splits[self.spy].SplitFactor)
            if split_factor > 0:
                self.lots["A"] = int(self.lots["A"] * split_factor)

    def _submit_buy(self, slot, symbol, quantity):
        tag = "{}_BUY".format(slot)
        ticket = self.MarketOrder(symbol, quantity, tag=tag)

        self.pending_orders[slot] = ticket.OrderId

        if ticket.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            self.pending_orders[slot] = None

    def _submit_sell(self, slot, symbol):
        quantity = self.lots[slot]
        if quantity <= 0:
            return

        tag = "{}_SELL".format(slot)
        ticket = self.MarketOrder(symbol, -quantity, tag=tag)

        self.pending_orders[slot] = ticket.OrderId

        if ticket.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            self.pending_orders[slot] = None

    def OnOrderEvent(self, order_event):
        order = self.Transactions.GetOrderById(order_event.OrderId)
        if order is None:
            return

        tag = order.Tag
        if tag not in ("A_BUY", "A_SELL", "B_BUY", "B_SELL"):
            return

        slot = tag[0]
        side = tag[2:]
        fill_quantity = int(order_event.FillQuantity)

        if fill_quantity != 0:
            if side == "BUY":
                self.lots[slot] += max(0, fill_quantity)
            elif side == "SELL":
                self.lots[slot] = max(0, self.lots[slot] + fill_quantity)

        if order_event.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            if self.pending_orders[slot] == order_event.OrderId:
                self.pending_orders[slot] = None
