        if data.Bars.ContainsKey(self.spy):
            self._update_spy_state(data.Bars[self.spy].Close)

        if data.Bars.ContainsKey(self.aapl):
            self._update_aapl_state(data.Bars[self.aapl].Close)

        if not all(data.Bars.ContainsKey(symbol) for symbol in self.required_symbols):
            return

        if self.IsWarmingUp:
            return

        # Evaluate all sells before any buys.
        if (
            self.lots["A"] > 0
            and "A" not in self.pending_orders
            and self.spy_cross_below
        ):
            self._submit_sell("A", self.spy, self.lots["A"])

        if (
            self.lots["B"] > 0
            and "B" not in self.pending_orders
            and self.aapl_rsi.IsReady
            and self.aapl_rsi.Current.Value > 60.0
        ):
            self._submit_sell("B", self.aapl, self.lots["B"])

        # Strategy A buy.
        if (
            self.lots["A"] == 0
            and "A" not in self.pending_orders
            and self.spy_cross_above
        ):
            close = float(data.Bars[self.spy].Close)
            target_value = 0.40 * float(self.Portfolio.TotalPortfolioValue)
            quantity = math.floor(target_value / close)

            if quantity > 0:
                self._submit_buy("A", self.spy, quantity)

        # Strategy B buy.
        if (
            self.lots["B"] == 0
            and "B" not in self.pending_orders
            and self.aapl_red_streak >= 3
        ):
            close = float(data.Bars[self.aapl].Close)
            available_cash = float(self.Portfolio.Cash)

            if available_cash >= self.AAPL_BUY_AMOUNT:
                quantity = math.floor(self.AAPL_BUY_AMOUNT / close)

                if quantity > 0:
                    self._submit_buy("B", self.aapl, quantity)

