        previous_sma = None

        if len(self.spy_closes) == self.SMA_PERIOD:
            previous_sma = sum(self.spy_closes) / self.SMA_PERIOD

        self.spy_cross_above = False
        self.spy_cross_below = False

        self.spy_closes.append(float(close))

        if len(self.spy_closes) == self.SMA_PERIOD:
            current_sma = sum(self.spy_closes) / self.SMA_PERIOD

            if (
                previous_sma is not None
                and self.previous_spy_close is not None
            ):
                self.spy_cross_above = (
                    self.previous_spy_close <= previous_sma
                    and float(close) > current_sma
                )

                self.spy_cross_below = (
                    self.previous_spy_close >= previous_sma
                    and float(close) < current_sma
                )

        self.previous_spy_close = float(close)

    def _update_aapl_state(self, close):
        close = float(close)

        if self.previous_aapl_close is None:
            self.aapl_red_streak = 0
        elif close < self.previous_aapl_close:
            self.aapl_red_streak += 1
        else:
            self.aapl_red_streak = 0

        self.previous_aapl_close = close

    def _submit_buy(self, strategy, symbol, quantity):
        self.pending_orders.add(strategy)

        try:
            ticket = self.MarketOrder(
                symbol,
                quantity,
                tag="{}|BUY".format(strategy)
            )

            if ticket.Status == OrderStatus.Invalid:
                self.pending_orders.discard(strategy)
        except Exception:
            self.pending_orders.discard(strategy)
            raise

    def _submit_sell(self, strategy, symbol, quantity):
        self.pending_orders.add(strategy)

        try:
            ticket = self.MarketOrder(
                symbol,
                -quantity,
                tag="{}|SELL".format(strategy)
            )

            if ticket.Status == OrderStatus.Invalid:
                self.pending_orders.discard(strategy)
        except Exception:
            self.pending_orders.discard(strategy)
            raise

    def OnOrderEvent(self, order_event):
        try:
            order = self.Transactions.GetOrderById(order_event.OrderId)
        except Exception:
            return

        if order is None or not order.Tag:
            return

        parts = order.Tag.split("|")
        if len(parts) != 2:
            return

        strategy = parts[0]
        side = parts[1]

        if strategy not in self.lots:
            return

        if order_event.Status in (
            OrderStatus.PartiallyFilled,
            OrderStatus.Filled
        ):
            fill_quantity = int(order_event.FillQuantity)

            if side == "BUY":
                self.lots[strategy] += fill_quantity
            elif side == "SELL":
                self.lots[strategy] += fill_quantity

        if order_event.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            self.pending_orders.discard(strategy)
