from AlgorithmImports import *
from collections import deque
import math


class DailyStrategySystem(QCAlgorithm):
    SMA_PERIOD = 20
    RSI_PERIOD = 14
    AAPL_BUY_AMOUNT = 20000.0

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.required_symbols = [
            self.spy,
            self.aapl,
            self.ibm,
            self.bac,
            self.aig
        ]

        self.SetWarmUp(
            max(self.SMA_PERIOD, self.RSI_PERIOD + 1),
            Resolution.Daily
        )

        self.spy_closes = deque(maxlen=self.SMA_PERIOD)
        self.spy_sma = None
        self.previous_spy_close = None
        self.previous_spy_sma = None

        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.rsi_previous_close = None
        self.rsi_deltas = deque(maxlen=self.RSI_PERIOD)
        self.rsi_average_gain = None
        self.rsi_average_loss = None
        self.aapl_rsi = None

        self.lots = {
            "A": 0,
            "B": 0
        }

        self.pending_orders = {}
        self.order_details = {}

    def OnData(self, data):
        bars = data.Bars

        spy_bar = bars[self.spy] if self.spy in bars else None
        aapl_bar = bars[self.aapl] if self.aapl in bars else None

        if spy_bar is not None:
            self._update_spy_state(float(spy_bar.Close))

        if aapl_bar is not None:
            self._update_aapl_state(float(aapl_bar.Close))

        if any(symbol not in bars for symbol in self.required_symbols):
            return

        spy_close = float(spy_bar.Close)

        crosses_above_sma = False
        crosses_below_sma = False

        if (
            self.spy_sma is not None
            and self.previous_spy_close is not None
            and self.previous_spy_sma is not None
        ):
            crosses_above_sma = (
                self.previous_spy_close <= self.previous_spy_sma
                and spy_close > self.spy_sma
            )

            crosses_below_sma = (
                self.previous_spy_close >= self.previous_spy_sma
                and spy_close < self.spy_sma
            )

        if self.IsWarmingUp:
            return

        aapl_rsi_above_60 = (
            self.aapl_rsi is not None
            and self.aapl_rsi > 60.0
        )

        # Evaluate sells before buys.
        if (
            self.lots["A"] > 0
            and "A" not in self.pending_orders
            and crosses_below_sma
        ):
            self._submit_sell("A", self.spy, self.lots["A"])

        if (
            self.lots["B"] > 0
            and "B" not in self.pending_orders
            and aapl_rsi_above_60
        ):
            self._submit_sell("B", self.aapl, self.lots["B"])

        # Slot 1 buy.
        if (
            self.lots["A"] == 0
            and "A" not in self.pending_orders
            and crosses_above_sma
            and self.spy_sma is not None
        ):
            portfolio_value = float(self.Portfolio.TotalPortfolioValue)
            quantity = int(
                math.floor(
                    (0.40 * portfolio_value) / spy_close
                )
            )

            if quantity > 0:
                self._submit_buy("A", self.spy, quantity)

        # Slot 2 buy.
        if (
            self.lots["B"] == 0
            and "B" not in self.pending_orders
            and self.aapl_red_streak >= 3
        ):
            available_cash = float(self.Portfolio.Cash)

            if available_cash >= self.AAPL_BUY_AMOUNT:
                aapl_close = float(aapl_bar.Close)
                quantity = int(
                    math.floor(
                        self.AAPL_BUY_AMOUNT / aapl_close
                    )
                )

                if quantity > 0:
                    self._submit_buy("B", self.aapl, quantity)

    def _update_spy_state(self, close):
        self.spy_closes.append(close)

        if len(self.spy_closes) == self.SMA_PERIOD:
            self.spy_sma = sum(self.spy_closes) / self.SMA_PERIOD
        else:
            self.spy_sma = None

        self.previous_spy_close = close
        if self.spy_sma is not None:
            self.previous_spy_sma = self.spy_sma

    def _update_aapl_state(self, close):
        if self.previous_aapl_close is not None:
            if close < self.previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        self.previous_aapl_close = close

        if self.rsi_previous_close is None:
            self.rsi_previous_close = close
            return

        delta = close - self.rsi_previous_close
        gain = max(delta, 0.0)
        loss = max(-delta, 0.0)

        self.rsi_previous_close = close

        if self.rsi_average_gain is None:
            self.rsi_deltas.append((gain, loss))

            if len(self.rsi_deltas) == self.RSI_PERIOD:
                self.rsi_average_gain = (
                    sum(item[0] for item in self.rsi_deltas)
                    / self.RSI_PERIOD
                )
                self.rsi_average_loss = (
                    sum(item[1] for item in self.rsi_deltas)
                    / self.RSI_PERIOD
                )
                self.aapl_rsi = self._calculate_rsi()
        else:
            self.rsi_average_gain = (
                (
                    self.rsi_average_gain * (self.RSI_PERIOD - 1)
                ) + gain
            ) / self.RSI_PERIOD

            self.rsi_average_loss = (
                (
                    self.rsi_average_loss * (self.RSI_PERIOD - 1)
                ) + loss
            ) / self.RSI_PERIOD

            self.aapl_rsi = self._calculate_rsi()

    def _calculate_rsi(self):
        if self.rsi_average_loss == 0:
            return 100.0

        relative_strength = (
            self.rsi_average_gain / self.rsi_average_loss
        )
        return 100.0 - (100.0 / (1.0 + relative_strength))

    def _submit_buy(self, slot, symbol, quantity):
        if quantity <= 0 or slot in self.pending_orders:
            return

        self.pending_orders[slot] = "buy"

        ticket = self.MarketOrder(
            symbol,
            quantity,
            tag="Strategy {} buy".format(slot)
        )

        if ticket is None:
            self.pending_orders.pop(slot, None)
            return

        if ticket.Status in (
            OrderStatus.Invalid,
            OrderStatus.Canceled
        ):
            self.pending_orders.pop(slot, None)
            return

        if ticket.Status == OrderStatus.Filled:
            self.lots[slot] += int(ticket.Quantity)
            self.pending_orders.pop(slot, None)
            return

        self.order_details[ticket.OrderId] = (
            slot,
            "buy"
        )

    def _submit_sell(self, slot, symbol, quantity):
        if quantity <= 0 or slot in self.pending_orders:
            return

        self.pending_orders[slot] = "sell"

        ticket = self.MarketOrder(
            symbol,
            -quantity,
            tag="Strategy {} sell".format(slot)
        )

        if ticket is None:
            self.pending_orders.pop(slot, None)
            return

        if ticket.Status in (
            OrderStatus.Invalid,
            OrderStatus.Canceled
        ):
            self.pending_orders.pop(slot, None)
            return

        if ticket.Status == OrderStatus.Filled:
            self.lots[slot] = max(
                0,
                self.lots[slot] + int(ticket.Quantity)
            )
            self.pending_orders.pop(slot, None)
            return

        self.order_details[ticket.OrderId] = (
            slot,
            "sell"
        )

    def OnOrderEvent(self, order_event):
        details = self.order_details.get(order_event.OrderId)

        if details is None:
            return

        slot, action = details

        if order_event.FillQuantity != 0:
            self.lots[slot] = max(
                0,
                self.lots[slot] + int(order_event.FillQuantity)
            )

        if order_event.Status == OrderStatus.Filled:
            self.pending_orders.pop(slot, None)
            self.order_details.pop(order_event.OrderId, None)

        elif order_event.Status in (
            OrderStatus.Invalid,
            OrderStatus.Canceled
        ):
            self.pending_orders.pop(slot, None)
            self.order_details.pop(order_event.OrderId, None)
