from AlgorithmImports import *
import math


class ExactStrategySystemAlgorithm(QCAlgorithm):
    SMA_PERIOD = 200
    RSI_PERIOD = 14
    RSI_SELL_LEVEL = 60.0
    AAPL_BUY_AMOUNT = 20000.0

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.required_symbols = [
            self.spy,
            self.aapl,
            self.ibm,
            self.bac,
            self.aig
        ]

        self.spy_sma = self.SMA(
            self.spy,
            self.SMA_PERIOD,
            Resolution.Daily
        )

        self.aapl_rsi = self.RSI(
            self.aapl,
            self.RSI_PERIOD,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.SetWarmUp(self.SMA_PERIOD, Resolution.Daily)

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.pending_orders = {
            "A": False,
            "B": False
        }

    def OnData(self, data):
        bars = data.Bars

        spy_bar = bars[self.spy] if bars.ContainsKey(self.spy) else None
        aapl_bar = bars[self.aapl] if bars.ContainsKey(self.aapl) else None

        previous_spy_close = self.previous_spy_close
        previous_spy_sma = self.previous_spy_sma
        current_spy_close = None
        current_spy_sma = None

        if spy_bar is not None:
            current_spy_close = float(spy_bar.Close)
            if self.spy_sma.IsReady:
                current_spy_sma = float(self.spy_sma.Current.Value)

        if aapl_bar is not None:
            current_aapl_close = float(aapl_bar.Close)

            if self.previous_aapl_close is None:
                self.aapl_red_streak = 0
            elif current_aapl_close < self.previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        all_bars_present = all(
            bars.ContainsKey(symbol) for symbol in self.required_symbols
        )

        if (
            all_bars_present
            and not self.IsWarmingUp
            and current_spy_close is not None
            and current_spy_sma is not None
            and previous_spy_close is not None
            and previous_spy_sma is not None
            and self.aapl_rsi.IsReady
            and aapl_bar is not None
        ):
            current_aapl_rsi = float(self.aapl_rsi.Current.Value)

            strategy_a_sell = (
                self.strategy_a_lot > 0
                and previous_spy_close <= previous_spy_sma
                and current_spy_close < current_spy_sma
            )

            strategy_b_sell = (
                self.strategy_b_lot > 0
                and current_aapl_rsi > self.RSI_SELL_LEVEL
            )

            if strategy_a_sell:
                self._liquidate_strategy_a()

            if strategy_b_sell:
                self._liquidate_strategy_b()

            strategy_a_buy = (
                self.strategy_a_lot == 0
                and not self.pending_orders["A"]
                and previous_spy_close <= previous_spy_sma
                and current_spy_close > current_spy_sma
            )

            strategy_b_buy = (
                self.strategy_b_lot == 0
                and not self.pending_orders["B"]
                and self.aapl_red_streak >= 3
            )

            if strategy_a_buy:
                portfolio_value = float(self.Portfolio.TotalPortfolioValue)
                shares = int(
                    math.floor(
                        (0.40 * portfolio_value) / current_spy_close
                    )
                )

                if shares > 0:
                    self._submit_order(
                        "A",
                        self.spy,
                        shares,
                        "Strategy A Buy"
                    )

            if strategy_b_buy:
                available_cash = float(self.Portfolio.Cash)

                if available_cash >= self.AAPL_BUY_AMOUNT:
                    shares = int(
                        math.floor(
                            self.AAPL_BUY_AMOUNT / current_aapl_close
                        )
                    )

                    if shares > 0:
                        self._submit_order(
                            "B",
                            self.aapl,
                            shares,
                            "Strategy B Buy"
                        )

        if spy_bar is not None:
            self.previous_spy_close = current_spy_close
            if current_spy_sma is not None:
                self.previous_spy_sma = current_spy_sma

        if aapl_bar is not None:
            self.previous_aapl_close = current_aapl_close

    def _liquidate_strategy_a(self):
        if self.strategy_a_lot > 0 and not self.pending_orders["A"]:
            self._submit_order(
                "A",
                self.spy,
                -self.strategy_a_lot,
                "Strategy A Sell"
            )

    def _liquidate_strategy_b(self):
        if self.strategy_b_lot > 0 and not self.pending_orders["B"]:
            self._submit_order(
                "B",
                self.aapl,
                -self.strategy_b_lot,
                "Strategy B Sell"
            )

    def _submit_order(self, strategy, symbol, quantity, tag):
        self.pending_orders[strategy] = True
        ticket = self.MarketOrder(symbol, quantity, tag=tag)

        if ticket is None:
            self.pending_orders[strategy] = False
            return

        if ticket.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
            self.pending_orders[strategy] = False

    def OnOrderEvent(self, order_event):
        order = self.Transactions.GetOrderById(order_event.OrderId)
        if order is None:
            return

        tag = order.Tag
        fill_quantity = int(order_event.FillQuantity)

        if tag == "Strategy A Buy":
            if fill_quantity > 0:
                self.strategy_a_lot += fill_quantity
            self._update_order_status("A", order_event.Status)

        elif tag == "Strategy A Sell":
            if fill_quantity != 0:
                self.strategy_a_lot = max(
                    0,
                    self.strategy_a_lot + fill_quantity
                )
            self._update_order_status("A", order_event.Status)

        elif tag == "Strategy B Buy":
            if fill_quantity > 0:
                self.strategy_b_lot += fill_quantity
            self._update_order_status("B", order_event.Status)

        elif tag == "Strategy B Sell":
            if fill_quantity != 0:
                self.strategy_b_lot = max(
                    0,
                    self.strategy_b_lot + fill_quantity
                )
            self._update_order_status("B", order_event.Status)

    def _update_order_status(self, strategy, status):
        if status in [
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ]:
            self.pending_orders[strategy] = False
