    RSI_PERIOD = 14
    AAPL_BUY_AMOUNT = 20000.0

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.required_symbols = [
            self.spy,
            self.aapl,
            self.ibm,
            self.bac,
            self.aig
        ]

        self.spy_sma = self.SMA(self.spy, self.SMA_PERIOD, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.aapl,
            self.RSI_PERIOD,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.SetWarmUp(self.SMA_PERIOD + self.RSI_PERIOD + 5, Resolution.Daily)

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.pending_orders = {}

    def OnData(self, data):
        spy_close = None
        aapl_close = None

        if self.spy in data.Bars:
            spy_close = float(data.Bars[self.spy].Close)

        if self.aapl in data.Bars:
            aapl_close = float(data.Bars[self.aapl].Close)

        if aapl_close is not None:
            if self.previous_aapl_close is not None:
                if aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

        spy_sma_value = None
        if self.spy_sma.IsReady:
            spy_sma_value = float(self.spy_sma.Current.Value)

        spy_crosses_above = False
        spy_crosses_below = False

        if (
            spy_close is not None
            and spy_sma_value is not None
            and self.previous_spy_close is not None
            and self.previous_spy_sma is not None
        ):
            spy_crosses_above = (
                self.previous_spy_close <= self.previous_spy_sma
                and spy_close > spy_sma_value
            )
            spy_crosses_below = (
                self.previous_spy_close >= self.previous_spy_sma
                and spy_close < spy_sma_value
            )

        all_bars_present = all(
            symbol in data.Bars for symbol in self.required_symbols
        )

        if (
            all_bars_present
            and not self.IsWarmingUp
            and spy_crosses_below
            and self.strategy_a_lot > 0
        ):
            self._submit_order(
                self.spy,
                -self.strategy_a_lot,
                "A",
                "Strategy A sell"
            )

        if (
            all_bars_present
            and not self.IsWarmingUp
            and self.aapl_rsi.IsReady
            and float(self.aapl_rsi.Current.Value) > 60.0
            and self.strategy_b_lot > 0
        ):
            self._submit_order(
                self.aapl,
                -self.strategy_b_lot,
                "B",
                "Strategy B sell"
            )

        if (
            all_bars_present
            and not self.IsWarmingUp
            and spy_crosses_above
            and self.strategy_a_lot == 0
            and spy_close is not None
        ):
            target_value = 0.40 * float(self.Portfolio.TotalPortfolioValue)
            quantity = int(target_value / spy_close)

            if quantity > 0:
                self._submit_order(
                    self.spy,
                    quantity,
                    "A",
                    "Strategy A buy"
                )

        if (
            all_bars_present
            and not self.IsWarmingUp
            and self.strategy_b_lot == 0
            and self.aapl_red_streak >= 3
            and aapl_close is not None
        ):
            if float(self.Portfolio.Cash) >= self.AAPL_BUY_AMOUNT:
                quantity = int(self.AAPL_BUY_AMOUNT / aapl_close)

                if quantity > 0:
                    self._submit_order(
                        self.aapl,
                        quantity,
                        "B",
                        "Strategy B buy"
                    )

        if spy_close is not None:
            self.previous_spy_close = spy_close
            if spy_sma_value is not None:
                self.previous_spy_sma = spy_sma_value

        if aapl_close is not None:
            self.previous_aapl_close = aapl_close

    def _submit_order(self, symbol, quantity, slot, tag):
        if quantity == 0:
            return

        ticket = self.MarketOrder(symbol, quantity, tag=tag)

        if ticket is None:
            return

        if ticket.Status == OrderStatus.Filled:
            self._update_lot(slot, int(ticket.Quantity))
        else:
            self.pending_orders[ticket.OrderId] = slot

    def OnOrderEvent(self, order_event):
        slot = self.pending_orders.get(order_event.OrderId)

        if slot is None:
            return

        if order_event.Status in (
            OrderStatus.PartiallyFilled,
            OrderStatus.Filled
        ):
            self._update_lot(slot, int(order_event.FillQuantity))

        if order_event.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            self.pending_orders.pop(order_event.OrderId, None)

    def _update_lot(self, slot, quantity):
        if slot == "A":
            self.strategy_a_lot = max(0, self.strategy_a_lot + quantity)
        elif slot == "B":
            self.strategy_b_lot = max(0, self.strategy_b_lot + quantity)
