from AlgorithmImports import *
from collections import deque
import math


class DailyCrossAndRSIAlgorithm(QCAlgorithm):
    SMA_PERIOD = 20
    RSI_PERIOD = 14

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily, fillForward=False).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily, fillForward=False).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily, fillForward=False).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily, fillForward=False).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily, fillForward=False).Symbol

        self.rsi = self.RSI(
            self.aapl,
            self.RSI_PERIOD,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.spy_closes = deque(maxlen=self.SMA_PERIOD)
        self.previous_spy_close = None
        self.previous_spy_sma = None

        self.spy_crossed_above = False
        self.spy_crossed_below = False

        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.lots = {
            "A": 0,
            "B": 0
        }

        self.pending_orders = {
            "A": None,
            "B": None
        }

        self.SetWarmUp(250, Resolution.Daily)

    def OnData(self, data):
        self._update_market_state(data)
        self._adjust_lots_for_splits(data)

        if self.IsWarmingUp:
            return

        required_symbols = [
            self.spy,
            self.aapl,
            self.ibm,
            self.bac,
            self.aig
        ]

        if not all(symbol in data.Bars for symbol in required_symbols):
            return

        self._evaluate_sells()
        self._evaluate_buys()

    def _update_market_state(self, data):
        if self.spy in data.Bars:
            spy_close = float(data.Bars[self.spy].Close)
            self.spy_crossed_above = False
            self.spy_crossed_below = False

            self.spy_closes.append(spy_close)

            if len(self.spy_closes) == self.SMA_PERIOD:
                current_sma = sum(self.spy_closes) / self.SMA_PERIOD

                if (
                    self.previous_spy_close is not None and
                    self.previous_spy_sma is not None
                ):
                    self.spy_crossed_above = (
                        self.previous_spy_close <= self.previous_spy_sma
                        and spy_close > current_sma
                    )

                    self.spy_crossed_below = (
                        self.previous_spy_close >= self.previous_spy_sma
                        and spy_close < current_sma
                    )

                self.previous_spy_sma = current_sma

            self.previous_spy_close = spy_close

        if self.aapl in data.Bars:
            aapl_close = float(data.Bars[self.aapl].Close)

            if self.previous_aapl_close is None:
                self.aapl_red_streak = 0
            elif aapl_close < self.previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

            self.previous_aapl_close = aapl_close

    def _adjust_lots_for_splits(self, data):
        if self.spy in data.Splits:
            split = data.Splits[self.spy]
            self.lots["A"] = int(round(self.lots["A"] * float(split.SplitFactor)))

        if self.aapl in data.Splits:
            split = data.Splits[self.aapl]
            self.lots["B"] = int(round(self.lots["B"] * float(split.SplitFactor)))

    def _evaluate_sells(self):
        if (
            self.lots["A"] > 0
            and self.pending_orders["A"] is None
            and self.spy_crossed_below
        ):
            self._submit_order("A", self.spy, -self.lots["A"], "Strategy A sell")

        if (
            self.lots["B"] > 0
            and self.pending_orders["B"] is None
            and self.rsi.IsReady
            and self.rsi.Current.Value > 60
        ):
            self._submit_order("B", self.aapl, -self.lots["B"], "Strategy B sell")

    def _evaluate_buys(self):
        if (
            self.lots["A"] == 0
            and self.pending_orders["A"] is None
            and self.spy_crossed_above
            and self.spy in self.Securities
        ):
            close = float(self.Securities[self.spy].Price)
            if close > 0:
                target_value = 0.40 * float(self.Portfolio.TotalPortfolioValue)
                quantity = int(math.floor(target_value / close))

                if quantity > 0:
                    self._submit_order(
                        "A",
                        self.spy,
                        quantity,
                        "Strategy A buy"
                    )

        if (
            self.lots["B"] == 0
            and self.pending_orders["B"] is None
            and self.aapl_red_streak >= 3
            and self.aapl in self.Securities
        ):
            available_cash = float(self.Portfolio.Cash)

            if available_cash >= 20000:
                close = float(self.Securities[self.aapl].Price)

                if close > 0:
                    quantity = int(math.floor(20000.0 / close))

                    if quantity > 0:
                        self._submit_order(
                            "B",
                            self.aapl,
                            quantity,
                            "Strategy B buy"
                        )

    def _submit_order(self, slot, symbol, quantity, tag):
        if quantity == 0 or self.pending_orders[slot] is not None:
            return

        ticket = self.MarketOrder(symbol, quantity, tag=tag)

        if ticket is None:
            return

        self.pending_orders[slot] = ticket.OrderId

        if ticket.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            self.pending_orders[slot] = None

    def OnOrderEvent(self, order_event):
        if order_event.Symbol == self.spy:
            slot = "A"
        elif order_event.Symbol == self.aapl:
            slot = "B"
        else:
            return

        fill_quantity = int(order_event.FillQuantity)

        if fill_quantity != 0:
            self.lots[slot] += fill_quantity

            if self.lots[slot] < 0:
                self.lots[slot] = 0

        if order_event.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            if self.pending_orders[slot] == order_event.OrderId:
                self.pending_orders[slot] = None
